130	template <typename ParamsT>
131	static void freeInputReq(InputReq<ParamsT>* ir)
132	{
133	    FeatureFreeValue(ir->params);
134	    FeatureFreeInstanceHandle(ir->handle);
135	    free(ir);
136	}
