138	template <typename ParamsT>
139	static int queue_async_work(
140	    FeatureInstanceHandle feature,
141	    FtPromiseId pid,
142	    ParamsT* setup_data,
143	    const char* operation_name,
144	    uv_work_cb work_cb)
145	{
146	    auto* ic = get_input_ctx(feature);
147	    if (!ic) {
148	        FEATURE_LOG_ERROR("%s : Failed to get input generator context.", file_tag);
149	        FeaturePromiseReject(feature, pid, GENERAL, "Failed to get input generator context");
150	        return -1;
151	    }
152	
153	    auto* req = static_cast<InputReq<ParamsT>*>(malloc(sizeof(InputReq<ParamsT>)));
154	    if (!req) {
155	        FEATURE_LOG_ERROR("%s : memory allocation failed.", file_tag);
156	        FeaturePromiseReject(feature, pid, GENERAL, "malloc fail");
157	        return -1;
158	    }
159	
160	    req->req.data = req;
161	    req->handle = FeatureDupInstanceHandle(feature);
162	    req->pid = pid;
163	    req->ic = ic;
164	    req->params = (ParamsT*)FeatureDupValue(setup_data);
165	
166	    int res = uv_queue_work(ic->loop, &req->req, work_cb, [](uv_work_t* _req, int status) {
167	        auto* ir = static_cast<InputReq<ParamsT>*>(_req->data);
168	
169	        if (!FeatureInstanceIsDetached(ir->handle)) {
170	            if (status != 0 || ir->result != 0) {
171	                FeaturePromiseReject(ir->handle, ir->pid, TASK_FAILED, "Perform error");
172	            } else {
173	                FeaturePromiseResolve(ir->handle, ir->pid);
174	            }
175	        }
176	
177	        freeInputReq(ir);
178	    });
179	
180	    if (res != 0) {
181	        FEATURE_LOG_ERROR("%s: execute uv_queue_work fail for %s", file_tag, operation_name);
182	        FeaturePromiseReject(feature, pid, TASK_FAILED, "uv_queue_work fail");
183	        freeInputReq(req);
184	        return -1;
185	    }
186	
187	    return 0;
188	}
