callback onError_cb(string message, int code)
callback onComplete_cb()
callback onSuccess_cb(object data)

// 订阅参数
struct SubscribeOptions {
    callback onNavigate_cb onNavigate
    callback onError_cb onError
    bool enableLongPress = true    // 是否启用长按检测
    int longPressThreshold = 500   // 长按阈值（毫秒）
}

// 查询结果
struct ButtonStatus {
    bool backPressed
    bool homePressed
    bool menuPressed
    long lastEventTime
}

// 查询参数
