```

### 4.2 C++ 实现框架 (`navigation_impl.cpp`)

```cpp
/*
 * Copyright (C) 2025 Your Company
 * Licensed under the Apache License, Version 2.0
 */

#include "navigation.h"
#include "feature_config.h"
#include "feature_exports.h"
#include "feature_log.h"
#include <uv.h>
#include <nuttx/input/buttons.h>  // NuttX buttons driver

static const char* file_tag = "[jidl_feature] navigation";

// GPIO 引脚定义（来自 board.h）
#define GPIO_KEY_BACK   17  // PH17
#define GPIO_KEY_HOME   18  // PH18
#define GPIO_KEY_MENU   19  // PH19

// 导航上下文
struct NavigationContext {
    uv_loop_t* loop;
    uv_poll_t button_poller;
    int button_fd;                      // /dev/buttons0 文件描述符
    FtCallbackId navigate_callback_id;  // 回调ID
    FeatureInstanceHandle handle;       // Feature 句柄
    bool long_press_enabled;
    int long_press_threshold;
    struct timeval last_press_time;
    int last_button;
};

// 全局上下文
static NavigationContext* g_nav_ctx = nullptr;

// Feature 生命周期回调
void system_board_navigation_onRegister(const char* feature_name)
{
    FEATURE_LOG_INFO("%s::%s() - Registering navigation feature\n", 
                     file_tag, __FUNCTION__);
}

void system_board_navigation_onCreate(FeatureRuntimeContext ctx, FeatureProtoHandle handle)
{
    FEATURE_LOG_INFO("%s::%s()\n", file_tag, __FUNCTION__);

    auto* nav_ctx = static_cast<NavigationContext*>(
        malloc(sizeof(NavigationContext)));

    if (!nav_ctx) {
        FEATURE_LOG_ERROR("%s: Failed to allocate navigation context\n", 
                         file_tag);
        return;
    }

    memset(nav_ctx, 0, sizeof(NavigationContext));

    // 获取 UV Loop
    FeatureManagerHandle manager = FeatureGetManagerHandleFromProto(handle);
    nav_ctx->loop = FeatureGetUVLoop(manager);

    // 打开按键设备
    nav_ctx->button_fd = open("/dev/buttons0", O_RDONLY | O_NONBLOCK);
    if (nav_ctx->button_fd < 0) {
        FEATURE_LOG_ERROR("%s: Failed to open /dev/buttons0: %d\n", 
                         file_tag, errno);
        free(nav_ctx);
        return;
    }

    FeatureSetProtoData(handle, nav_ctx);
    g_nav_ctx = nav_ctx;
}

void system_board_navigation_onRequired(FeatureRuntimeContext ctx, 
                                         FeatureInstanceHandle handle)
{
    FEATURE_LOG_DEBUG("%s::%s()\n", file_tag, __FUNCTION__);
}

void system_board_navigation_onDetached(FeatureRuntimeContext ctx, 
                                         FeatureInstanceHandle handle)
{
    FEATURE_LOG_DEBUG("%s::%s()\n", file_tag, __FUNCTION__);

    if (g_nav_ctx && g_nav_ctx->navigate_callback_id != 0) {
        FeatureRemoveCallback(handle, g_nav_ctx->navigate_callback_id);
        g_nav_ctx->navigate_callback_id = 0;
    }
}

void system_board_navigation_onDestroy(FeatureRuntimeContext ctx, 
                                        FeatureProtoHandle handle)
{
    FEATURE_LOG_INFO("%s::%s()\n", file_tag, __FUNCTION__);

    auto* nav_ctx = static_cast<NavigationContext*>(
        FeatureGetProtoData(handle));

    if (nav_ctx) {
        // 停止轮询
        uv_poll_stop(&nav_ctx->button_poller);

        // 关闭设备
        if (nav_ctx->button_fd >= 0) {
            close(nav_ctx->button_fd);
        }

        free(nav_ctx);
        g_nav_ctx = nullptr;
    }
}

void system_board_navigation_onUnregister(const char* feature_name)
{
    FEATURE_LOG_INFO("%s::%s()\n", file_tag, __FUNCTION__);
}

// 按键事件处理
static void button_poll_callback(uv_poll_t* handle, int status, int events)
{
    if (status < 0 || !(events & UV_READABLE)) {
        return;
    }

    auto* nav_ctx = static_cast<NavigationContext*>(handle->data);
    struct button_notify_s btn_data;

    ssize_t bytes_read = read(nav_ctx->button_fd, &btn_data, sizeof(btn_data));
    if (bytes_read != sizeof(btn_data)) {
        return;
    }

    // 映射物理按键到导航事件
    NavigationType nav_type;
    switch (btn_data.btn_id) {
        case BUTTON_KEY_BACK:
            nav_type = NAVIGATION_TYPE_LEFT;
            break;
        case BUTTON_KEY_HOME:
            nav_type = NAVIGATION_TYPE_HOME;
            break;
        case BUTTON_KEY_MENU:
            nav_type = NAVIGATION_TYPE_RIGHT;
            break;
        default:
            return;  // 忽略其他按键
    }

    // 创建事件对象
    struct NavigationEvent event;
    event.type = nav_type;
    event.timestamp = time(NULL) * 1000;  // 毫秒时间戳
    event.longPress = false;
    event.duration = 0;

    // 长按检测
    if (nav_ctx->long_press_enabled) {
        if (btn_data.action == BUTTON_PRESS) {
            gettimeofday(&nav_ctx->last_press_time, NULL);
            nav_ctx->last_button = btn_data.btn_id;
        } else if (btn_data.action == BUTTON_RELEASE) {
            struct timeval now;
            gettimeofday(&now, NULL);

            long duration_ms = (now.tv_sec - nav_ctx->last_press_time.tv_sec) * 1000 +
                               (now.tv_usec - nav_ctx->last_press_time.tv_usec) / 1000;

            if (duration_ms >= nav_ctx->long_press_threshold) {
                event.longPress = true;
                event.duration = duration_ms;
            }
        }
    }

    // 触发回调
    if (nav_ctx->navigate_callback_id != 0) {
        FeatureInvokeCallback(nav_ctx->handle, 
                            nav_ctx->navigate_callback_id, 
                            &event);
    }
}

// ======== Feature 方法实现 ========

// 订阅导航事件
void system_board_navigation_wrap_subscribe(
    FeatureInstanceHandle handle,
    AppendData append_data,
    system_board_navigation_SubscribeOptions* options)
{
    FEATURE_LOG_INFO("%s::%s()\n", file_tag, __FUNCTION__);

    if (!options || !options->onNavigate) {
        FEATURE_LOG_ERROR("%s: Invalid subscribe parameters\n", file_tag);
        return;
    }

    if (!g_nav_ctx) {
        FEATURE_LOG_ERROR("%s: Navigation context not initialized\n", file_tag);
        if (options->onError) {
            FeatureInvokeCallback(handle, options->onError, 
                                "Navigation not initialized", -1);
        }
        return;
    }

    // 保存回调
    g_nav_ctx->navigate_callback_id = options->onNavigate;
    g_nav_ctx->handle = handle;
    g_nav_ctx->long_press_enabled = options->enableLongPress;
    g_nav_ctx->long_press_threshold = options->longPressThreshold;

    // 设置 UV 轮询
    g_nav_ctx->button_poller.data = g_nav_ctx;
    uv_poll_init(g_nav_ctx->loop, &g_nav_ctx->button_poller, 
                 g_nav_ctx->button_fd);
    uv_poll_start(&g_nav_ctx->button_poller, UV_READABLE, 
                  button_poll_callback);

    FEATURE_LOG_INFO("%s: Navigation subscription started\n", file_tag);
}

// 取消订阅
void system_board_navigation_wrap_unsubscribe(
    FeatureInstanceHandle handle,
    AppendData append_data)
{
    FEATURE_LOG_INFO("%s::%s()\n", file_tag, __FUNCTION__);

    if (g_nav_ctx) {
        uv_poll_stop(&g_nav_ctx->button_poller);
        g_nav_ctx->navigate_callback_id = 0;
    }
}

// 获取按键状态
system_board_navigation_ButtonStatus* 
system_board_navigation_wrap_getButtonStatus(
    FeatureInstanceHandle handle,
    AppendData append_data)
{
    FEATURE_LOG_DEBUG("%s::%s()\n", file_tag, __FUNCTION__);

    auto* status = system_board_navigationMallocButtonStatus();
    if (!status) {
        return nullptr;
    }

    // 读取当前 GPIO 状态
    // 这里需要读取 /sys/class/gpio 或使用 ioctl
    status->backPressed = false;   // 需要实际读取 GPIO
    status->homePressed = false;
    status->menuPressed = false;
    status->lastEventTime = g_nav_ctx ? 
        g_nav_ctx->last_press_time.tv_sec * 1000 : 0;

    return status;
}
```

