### 4.1 JIDL 接口定义

**文件**：`frameworks/runtimes/feature/modules/jidl/navigation.jidl`

```idl
/*
 * Copyright (C) 2025 Your Company
 *
 * Licensed under the Apache License, Version 2.0
 */

module system.board.navigation@1.0

// ==================== 枚举定义 ====================

// 导航事件类型
enum NavigationType {
    LEFT = 0      // 向左（物理返回键 Key_Back）
    HOME = 1      // 首页（物理主页键 Key_Home）
    RIGHT = 2     // 向右（物理菜单键 Key_Menu）
}

// ==================== 结构体定义 ====================

// 按键事件数据
struct NavigationEvent {
    NavigationType type     // 导航类型
    long timestamp          // 事件时间戳（毫秒）
    bool longPress          // 是否长按
    int duration            // 按住时长（毫秒），短按时为 0
}

// 订阅参数
struct SubscribeOptions {
    callback onNavigate_cb onNavigate    // 导航事件回调（必填）
    callback onError_cb onError          // 错误回调（可选）
    bool enableLongPress = true          // 是否启用长按检测
    int longPressThreshold = 500         // 长按阈值（毫秒）
}

// 查询结果
struct ButtonStatus {
    bool backPressed         // 返回键是否按下
    bool homePressed         // 主页键是否按下
    bool menuPressed         // 菜单键是否按下
    long lastEventTime       // 最后事件时间戳
}

// 状态查询参数
struct StatusQueryParams {
    callback onSuccess_cb onSuccess
    callback onError_cb onError
    callback onComplete_cb onComplete
}

// ==================== 回调定义 ====================

// 导航事件回调
callback onNavigate_cb(NavigationEvent event)

// 错误回调
callback onError_cb(string message, int code)

// 成功回调
callback onSuccess_cb(object data)

// 完成回调
callback onComplete_cb()

// ==================== 方法定义 ====================

// 订阅导航事件（主要接口）
void subscribe(SubscribeOptions options)

// 取消所有订阅
void unsubscribe()

// 同步查询当前按键状态
ButtonStatus getButtonStatus()

// 异步查询按键状态（带回调）
void getStatus(StatusQueryParams params)

// 模拟导航事件（测试用，仅 Debug 模式可用）
promise simulateNavigation(NavigationType type)
```

