### 4.2 C++ 实现

**文件**：`frameworks/runtimes/feature/modules/navigation_impl.cpp`

```cpp
/*
 * Copyright (C) 2025 Your Company
 *
 * Licensed under the Apache License, Version 2.0
 */

#include "navigation.h"
#include "feature_config.h"
#include "feature_exports.h"
#include "feature_log.h"

#include <uv.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <errno.h>

#ifdef CONFIG_INPUT_BUTTONS
#  include <nuttx/input/buttons.h>
#endif

static const char* file_tag = "[jidl_feature] navigation";

/****************************************************************************
 * Private Types
 ****************************************************************************/

// GPIO 引脚定义（来自 board.h）
#define GPIO_KEY_BACK   17  // PH17
#define GPIO_KEY_HOME   18  // PH18
#define GPIO_KEY_MENU   19  // PH19

// 按键设备路径
#define BUTTONS_DEVICE_PATH "/dev/buttons0"

// 导航上下文
struct NavigationContext {
    uv_loop_t* loop;                    // UV 事件循环
    uv_poll_t button_poller;            // UV 轮询器
    int button_fd;                      // 按键设备文件描述符

    FtCallbackId navigate_callback_id;  // 导航回调 ID
    FtCallbackId error_callback_id;     // 错误回调 ID
    FeatureInstanceHandle handle;       // Feature 实例句柄

    bool long_press_enabled;            // 是否启用长按检测
    int long_press_threshold;           // 长按阈值（毫秒）

    struct timeval last_press_time;     // 上次按下时间
    int last_button;                    // 上次按下的按键

    bool subscribed;                    // 是否已订阅
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static NavigationContext* g_nav_ctx = nullptr;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

// 将物理按键 ID 映射为导航类型
static NavigationType map_button_to_navigation(int button_id)
{
    switch (button_id) {
        case BUTTON_KEY_BACK:
            return NAVIGATION_TYPE_LEFT;
        case BUTTON_KEY_HOME:
            return NAVIGATION_TYPE_HOME;
        case BUTTON_KEY_MENU:
            return NAVIGATION_TYPE_RIGHT;
        default:
            return NAVIGATION_TYPE_LEFT;  // 默认值
    }
}

// 按键轮询回调
static void button_poll_callback(uv_poll_t* handle, int status, int events)
{
    if (status < 0) {
        FEATURE_LOG_ERROR("%s: Poll error: %d\n", file_tag, status);
        return;
    }

    if (!(events & UV_READABLE)) {
        return;
    }

    auto* nav_ctx = static_cast<NavigationContext*>(handle->data);
    if (!nav_ctx || !nav_ctx->subscribed) {
        return;
    }

#ifdef CONFIG_INPUT_BUTTONS
    struct button_notify_s btn_data;
    ssize_t bytes_read = read(nav_ctx->button_fd, &btn_data, sizeof(btn_data));

    if (bytes_read != sizeof(btn_data)) {
        if (bytes_read < 0 && errno != EAGAIN) {
            FEATURE_LOG_ERROR("%s: Read error: %d\n", file_tag, errno);
        }
        return;
    }

    // 映射为导航事件
    NavigationType nav_type = map_button_to_navigation(btn_data.btn_id);

    // 创建事件对象
    system_board_navigation_NavigationEvent* event = 
        system_board_navigationMallocNavigationEvent();

    if (!event) {
        FEATURE_LOG_ERROR("%s: Failed to allocate event\n", file_tag);
        return;
    }

    event->type = nav_type;
    event->timestamp = (long)time(NULL) * 1000;
    event->longPress = false;
    event->duration = 0;

    // 长按检测
    if (nav_ctx->long_press_enabled) {
        if (btn_data.action == BUTTON_PRESS) {
            gettimeofday(&nav_ctx->last_press_time, NULL);
            nav_ctx->last_button = btn_data.btn_id;
        } else if (btn_data.action == BUTTON_RELEASE) {
            struct timeval now;
            gettimeofday(&now, NULL);

            long duration_ms = 
                (now.tv_sec - nav_ctx->last_press_time.tv_sec) * 1000 +
                (now.tv_usec - nav_ctx->last_press_time.tv_usec) / 1000;

            if (duration_ms >= nav_ctx->long_press_threshold) {
                event->longPress = true;
                event->duration = duration_ms;
            }
        }
    }

    // 触发回调
    if (nav_ctx->navigate_callback_id != 0) {
        FeatureInvokeCallback(nav_ctx->handle, 
                            nav_ctx->navigate_callback_id, 
                            event);
    }

    FeatureFreeValue(event);
#endif
}

/****************************************************************************
 * Feature Lifecycle Callbacks
 ****************************************************************************/

void system_board_navigation_onRegister(const char* feature_name)
{
    FEATURE_LOG_INFO("%s::%s() - Registering: %s\n", 
                     file_tag, __FUNCTION__, feature_name);
}

void system_board_navigation_onCreate(
    FeatureRuntimeContext ctx, 
    FeatureProtoHandle handle)
{
    FEATURE_LOG_INFO("%s::%s()\n", file_tag, __FUNCTION__);

    // 分配上下文
    auto* nav_ctx = static_cast<NavigationContext*>(
        malloc(sizeof(NavigationContext)));

    if (!nav_ctx) {
        FEATURE_LOG_ERROR("%s: Failed to allocate context\n", file_tag);
        return;
    }

    memset(nav_ctx, 0, sizeof(NavigationContext));

    // 获取 UV Loop
    FeatureManagerHandle manager = FeatureGetManagerHandleFromProto(handle);
    nav_ctx->loop = FeatureGetUVLoop(manager);

    // 打开按键设备
    nav_ctx->button_fd = open(BUTTONS_DEVICE_PATH, O_RDONLY | O_NONBLOCK);
    if (nav_ctx->button_fd < 0) {
        FEATURE_LOG_ERROR("%s: Failed to open %s: %d\n", 
                         file_tag, BUTTONS_DEVICE_PATH, errno);
        free(nav_ctx);
        return;
    }

    // 保存上下文
    FeatureSetProtoData(handle, nav_ctx);
    g_nav_ctx = nav_ctx;
}

void system_board_navigation_onRequired(
    FeatureRuntimeContext ctx, 
    FeatureInstanceHandle handle)
{
    FEATURE_LOG_DEBUG("%s::%s()\n", file_tag, __FUNCTION__);
}

void system_board_navigation_onDetached(
    FeatureRuntimeContext ctx, 
    FeatureInstanceHandle handle)
{
    FEATURE_LOG_DEBUG("%s::%s()\n", file_tag, __FUNCTION__);

    // 自动取消订阅
    if (g_nav_ctx && g_nav_ctx->subscribed) {
        uv_poll_stop(&g_nav_ctx->button_poller);
        g_nav_ctx->subscribed = false;
        g_nav_ctx->navigate_callback_id = 0;
    }
}

void system_board_navigation_onDestroy(
    FeatureRuntimeContext ctx, 
    FeatureProtoHandle handle)
{
    FEATURE_LOG_INFO("%s::%s()\n", file_tag, __FUNCTION__);

    auto* nav_ctx = static_cast<NavigationContext*>(
        FeatureGetProtoData(handle));

    if (nav_ctx) {
        // 停止轮询
        if (nav_ctx->subscribed) {
            uv_poll_stop(&nav_ctx->button_poller);
        }

        // 关闭设备
        if (nav_ctx->button_fd >= 0) {
            close(nav_ctx->button_fd);
        }

        free(nav_ctx);
        g_nav_ctx = nullptr;
    }
}

void system_board_navigation_onUnregister(const char* feature_name)
{
    FEATURE_LOG_INFO("%s::%s()\n", file_tag, __FUNCTION__);
}

/****************************************************************************
 * Feature Method Implementations
 ****************************************************************************/

// 订阅导航事件
void system_board_navigation_wrap_subscribe(
    FeatureInstanceHandle handle,
    AppendData append_data,
    system_board_navigation_SubscribeOptions* options)
{
    FEATURE_LOG_INFO("%s::%s()\n", file_tag, __FUNCTION__);

    // 参数检查
    if (!options || !options->onNavigate) {
        FEATURE_LOG_ERROR("%s: Invalid subscribe parameters\n", file_tag);
        return;
    }

    if (!g_nav_ctx) {
        FEATURE_LOG_ERROR("%s: Context not initialized\n", file_tag);
        if (options->onError) {
            FeatureInvokeCallback(handle, options->onError, 
                                "Navigation not initialized", -1);
        }
        return;
    }

    // 如果已经订阅，先取消
    if (g_nav_ctx->subscribed) {
        uv_poll_stop(&g_nav_ctx->button_poller);
    }

    // 保存配置
    g_nav_ctx->navigate_callback_id = options->onNavigate;
    g_nav_ctx->error_callback_id = options->onError;
    g_nav_ctx->handle = handle;
    g_nav_ctx->long_press_enabled = options->enableLongPress;
    g_nav_ctx->long_press_threshold = options->longPressThreshold;
    g_nav_ctx->subscribed = true;

    // 初始化 UV 轮询
    g_nav_ctx->button_poller.data = g_nav_ctx;
    uv_poll_init(g_nav_ctx->loop, &g_nav_ctx->button_poller, 
                 g_nav_ctx->button_fd);
    uv_poll_start(&g_nav_ctx->button_poller, UV_READABLE, 
                  button_poll_callback);

    FEATURE_LOG_INFO("%s: Subscription started\n", file_tag);
}

// 取消订阅
void system_board_navigation_wrap_unsubscribe(
    FeatureInstanceHandle handle,
    AppendData append_data)
{
    FEATURE_LOG_INFO("%s::%s()\n", file_tag, __FUNCTION__);

    if (g_nav_ctx && g_nav_ctx->subscribed) {
        uv_poll_stop(&g_nav_ctx->button_poller);
        g_nav_ctx->subscribed = false;
        g_nav_ctx->navigate_callback_id = 0;
        g_nav_ctx->error_callback_id = 0;

        FEATURE_LOG_INFO("%s: Unsubscribed\n", file_tag);
    }
}

// 同步获取按键状态
system_board_navigation_ButtonStatus* 
system_board_navigation_wrap_getButtonStatus(
    FeatureInstanceHandle handle,
    AppendData append_data)
{
    FEATURE_LOG_DEBUG("%s::%s()\n", file_tag, __FUNCTION__);

    auto* status = system_board_navigationMallocButtonStatus();
    if (!status) {
        return nullptr;
    }

    // 初始化默认值
    status->backPressed = false;
    status->homePressed = false;
    status->menuPressed = false;
    status->lastEventTime = 0;

    // 读取 GPIO 状态
    // 注意：实际实现需要读取 GPIO 或使用 ioctl
    // 这里简化处理，实际需要根据 NuttX GPIO 框架实现

    if (g_nav_ctx) {
        status->lastEventTime = 
            (long)g_nav_ctx->last_press_time.tv_sec * 1000;
    }

    return status;
}
