## 🚀 五、快应用使用示例

### 5.1 基础用法

```javascript
import system from '@system'

// 订阅导航事件
system.board.navigation.subscribe({
  onNavigate: (event) => {
    console.log(`Navigation: ${event.type}`)
    console.log(`Long press: ${event.longPress}`)
    console.log(`Duration: ${event.duration}ms`)

    switch (event.type) {
      case 0:  // LEFT
        router.back()
        break
      case 1:  // HOME
        router.push({ uri: '/pages/index' })
        break
      case 2:  // RIGHT
        // 跳转到下一页或打开菜单
        openMenu()
        break
    }
  },
  onError: (message, code) => {
    console.error(`Navigation error: ${message} (${code})`)
  },
  enableLongPress: true,
  longPressThreshold: 500
})
```

### 5.2 页面切换动画

```javascript
import system from '@system'

Page({
  onInit() {
    this.currentPage = 0
    this.totalPages = 5

    system.board.navigation.subscribe({
      onNavigate: (event) => {
        if (event.type === 0 && this.currentPage > 0) {
          // 向左
          this.animateTransition('left')
          this.currentPage--
        } else if (event.type === 2 && this.currentPage < this.totalPages - 1) {
          // 向右
          this.animateTransition('right')
          this.currentPage++
        } else if (event.type === 1) {
          // 回首页
          this.animateTransition('home')
          this.currentPage = 0
        }
      }
    })
  },

  onDestroy() {
    system.board.navigation.unsubscribe()
  },

  animateTransition(direction) {
    // 实现页面切换动画
  }
})
```

### 5.3 查询按键状态

```javascript
// 同步查询
const status = system.board.navigation.getButtonStatus()
console.log('Back pressed:', status.backPressed)
console.log('Home pressed:', status.homePressed)
console.log('Menu pressed:', status.menuPressed)

// 异步查询
system.board.navigation.getStatus({
  onSuccess: (data) => {
    console.log('Button status:', JSON.stringify(data))
  },
  onError: (msg, code) => {
    console.error('Query failed:', msg)
  }
})
