// ==================== Enum Definitions ====================

// Navigation event types
enum NavigationType {
    LEFT = 0      // Navigate left (Key_Back physical button)
    HOME = 1      // Navigate home (Key_Home physical button)
    RIGHT = 2     // Navigate right (Key_Menu physical button)
}

// ==================== Struct Definitions ====================

// Navigation event data
struct NavigationEvent {
    NavigationType type     // Navigation type
    long timestamp          // Event timestamp in milliseconds
    bool longPress          // Whether it's a long press
    int duration            // Press duration in ms, 0 for short press
}

// Subscribe options
struct SubscribeOptions {
    callback onNavigate_cb onNavigate    // Navigation event callback (required)
    callback onError_cb onError          // Error callback (optional)
    bool enableLongPress = true          // Enable long press detection
    int longPressThreshold = 500         // Long press threshold in milliseconds
}

// Button status query result
struct ButtonStatus {
    bool backPressed         // Whether back button is pressed
    bool homePressed         // Whether home button is pressed
    bool menuPressed         // Whether menu button is pressed
    long lastEventTime       // Last event timestamp
}

// Status query parameters
struct StatusQueryParams {
    callback onSuccess_cb onSuccess
    callback onError_cb onError
    callback onComplete_cb onComplete
}

// ==================== Callback Definitions ====================

// Navigation event callback
callback onNavigate_cb(NavigationEvent event)

// Error callback
callback onError_cb(string message, int code)

// Success callback
callback onSuccess_cb(object data)

// Complete callback
callback onComplete_cb()

// ==================== Method Definitions ====================

// Subscribe to navigation events (primary interface)
void subscribe(SubscribeOptions options)

// Unsubscribe all listeners
void unsubscribe()

// Synchronous button status query
ButtonStatus getButtonStatus()

// Asynchronous button status query with callbacks
void getStatus(StatusQueryParams params)

// Simulate navigation event (for testing, debug mode only)
promise simulateNavigation(NavigationType type)

