/**
 * Test script for system.board.navigation feature
 *
 * Usage:
 *   - Run this script in quick app environment
 *   - Press physical buttons on Gemini-S1 board
 *   - Observe console output
 */

import system from '@system'

console.log('=== Navigation Feature Test ===')

// Test 1: Basic subscription
function testSubscribe() {
  console.log('\n[Test 1] Basic Subscription')

  system.board.navigation.subscribe({
    onNavigate: (event) => {
      const typeNames = ['LEFT', 'HOME', 'RIGHT']
      console.log(`Navigation Event:`)
      console.log(`  Type: ${typeNames[event.type]} (${event.type})`)
      console.log(`  Long Press: ${event.longPress}`)
      console.log(`  Duration: ${event.duration}ms`)
      console.log(`  Timestamp: ${event.timestamp}`)
    },
    onError: (message, code) => {
      console.error(`Error: ${message} (${code})`)
    },
    enableLongPress: true,
    longPressThreshold: 500
  })

  console.log('Subscription started. Press buttons to test...')
}

// Test 2: Long press detection
function testLongPress() {
  console.log('\n[Test 2] Long Press Detection')

  let pressStartTime = 0

  system.board.navigation.subscribe({
    onNavigate: (event) => {
      if (event.longPress) {
        console.log(`✓ Long press detected!`)
        console.log(`  Duration: ${event.duration}ms`)
      } else {
        console.log(`○ Short press`)
      }
    },
    enableLongPress: true,
    longPressThreshold: 1000  // 1 second threshold
  })

  console.log('Press and hold button for 1+ seconds...')
}

// Test 3: Button status query
function testButtonStatus() {
  console.log('\n[Test 3] Button Status Query')

  // Synchronous query
  const status = system.board.navigation.getButtonStatus()
  console.log('Button Status:')
  console.log(`  Back: ${status.backPressed ? 'PRESSED' : 'released'}`)
  console.log(`  Home: ${status.homePressed ? 'PRESSED' : 'released'}`)
  console.log(`  Menu: ${status.menuPressed ? 'PRESSED' : 'released'}`)
  console.log(`  Last Event: ${new Date(status.lastEventTime).toLocaleString()}`)

  // Async query
  system.board.navigation.getStatus({
    onSuccess: (data) => {
      console.log('Async status:', JSON.stringify(data))
    },
    onError: (msg, code) => {
      console.error('Query failed:', msg)
    }
  })
}

// Test 4: Page navigation simulation
function testPageNavigation() {
  console.log('\n[Test 4] Page Navigation Simulation')

  let currentPage = 0
  const totalPages = 5

  const pages = [
    'Home',
    'Settings',
    'Profile',
    'About',
    'Help'
  ]

  console.log(`Current page: ${pages[currentPage]}`)

  system.board.navigation.subscribe({
    onNavigate: (event) => {
      switch (event.type) {
        case 0:  // LEFT
          if (currentPage > 0) {
            currentPage--
            console.log(`← Navigate Left`)
          } else {
            console.log(`← Already at first page`)
          }
          break

        case 1:  // HOME
          currentPage = 0
          console.log(`🏠 Navigate Home`)
          break

        case 2:  // RIGHT
          if (currentPage < totalPages - 1) {
            currentPage++
            console.log(`→ Navigate Right`)
          } else {
            console.log(`→ Already at last page`)
          }
          break
      }

      console.log(`Current page: ${pages[currentPage]}`)
    }
  })

  console.log(`Total pages: ${totalPages}`)
  console.log('Use buttons to navigate between pages...')
}

// Test 5: Unsubscribe and cleanup
function testUnsubscribe() {
  console.log('\n[Test 5] Unsubscribe')

  // First subscribe
  system.board.navigation.subscribe({
    onNavigate: (event) => {
      console.log('This should not print after unsubscribe')
    }
  })

  // Then unsubscribe
  setTimeout(() => {
    system.board.navigation.unsubscribe()
    console.log('✓ Unsubscribed successfully')
    console.log('Button presses should no longer trigger callbacks')
  }, 5000)
}

// Run tests
console.log('\nAvailable tests:')
console.log('1. testSubscribe()     - Basic subscription')
console.log('2. testLongPress()     - Long press detection')
console.log('3. testButtonStatus()  - Query button status')
console.log('4. testPageNavigation() - Page navigation demo')
console.log('5. testUnsubscribe()   - Unsubscribe and cleanup')
console.log('\nRun any test function to start...')

// Auto-run basic test
testSubscribe()
